// Shamelessly stolen from: 
// https://neort.io/art/c4oui2s3p9ffolj084vg?index=324&origin=tag
// But it is so .. beautiful i can't help it! ;)

uniform vec2 resolution;
uniform float time;
uniform vec2 mouse;
uniform sampler2D backbuffer;

#define t iTime
#define r iResolution.xy
#define FC fragCoord
#define o fragColor

vec3 hsv(float h, float s, float v) {
    vec4 a = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    vec3 p = abs(fract(vec3(h) + a.xyz) * 6.0 - vec3(a.w));
    return v * mix(vec3(a.x), clamp(p - vec3(a.x), 0.0, 1.0), s);
}

mat3 rotate3D(float angle, vec3 axis){
    vec3 a = normalize(axis);
    float s = sin(angle);
    float c = cos(angle);
    float rr = 1.0 - c;
    return mat3(
        a.x * a.x * rr + c,
        a.y * a.x * rr + a.z * s,
        a.z * a.x * rr - a.y * s,
        a.x * a.y * rr - a.z * s,
        a.y * a.y * rr + c,
        a.z * a.y * rr + a.x * s,
        a.x * a.z * rr + a.y * s,
        a.y * a.z * rr - a.x * s,
        a.z * a.z * rr + c
    );
}


void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    vec3 P,Q,S;
    P.z=9.;
    float d=1.,a;
    for(int i=0;i<99;i++){
        if(d<1e-4)break;
        Q=S=P*rotate3D(t,vec3(1,0,1));
        a=1.;
        for(int j=0;j<9;j++){
            Q=2.*clamp(Q,-.6,.6)-Q;
            d=clamp(dot(Q,Q),.1,1.)*.5;
            Q=Q/d+S;
            a=a/d+abs(cos(iTime))/d;
        }
        d=(length(Q)-9.)/a;
        P+=vec3((FC.xy-r*.5)/r.y,-1)*d;
        o.rgb+=max(0.17-d*d,0.0001)*hsv(dot(P,P)*.03,.8,min(a,4e4)*3e-5);

    }

}
